:root{
    --cor-fundo-principal: #0D111F;
    --cor-fundo-secundario: #1A2238;
    --cor-botao: #F5B700;

    --cor-texto-principal: #FFFFFF;
    --cor-texto-secundario: #B8C1D1;

    --radius-pequeno: 5px;
    --radius-grande: 8px;
}

*{
    margin: 0;
    padding: 0;
}

body{
    background-color: var(--cor-fundo-principal);
    font-family: Arial, Helvetica, sans-serif;
}

h1{
    color: var(--cor-botao);
    text-align: center;
    margin-top: 40px;
}

.grid{
    width: min(90%, 1400px);
    margin: 50px auto;
    display: grid;
    grid-template-columns:  
    repeat(auto-fit, minmax(300px, 1fr));
    gap: 30px;
}

.produto{
    background-color: var(--cor-fundo-secundario);
    border-radius: var(--radius-grande);
    overflow: hidden;
    transition:
    transform 0.3s ease,
    box-shadow 0.3s ease;
}

.produto:hover{
    transform: translateY(-5px);
}

.imagem-produto{
    width: 100%;
    height: 240px;
    overflow: hidden;
}

.imagem-produto img{
    width: 100%;
    height: 100%;
    object-fit: cover;
    display: block;
    color: var(--cor-texto-principal);
}

.conteudo-produto{
    padding: 22px;
}

.produto h2{
    color: var(--cor-texto-principal);
    margin-bottom: 15px;
}

.produto p{
    color: var(--cor-texto-secundario);
    line-height: 1.6;
}

.botao-principal{
    display: inline-block;
    margin-top: 20px;
    background-color: var(--cor-botao);
    color: #000;
    padding: 12px 18px;
    border-radius: var(--radius-pequeno);
    text-decoration: none;
    font-weight: bold;
    transition:
    background-color 0.3s ease,
    transform 0.3s ease;
}

